import { describe, expect, it } from 'vitest';
import { nodeBoxes, overallBounds, readGlb } from './glb.js';
import { GAME, machineGeometryFor } from '../src/game/config.js';

// The launcher is generated by tools/build_launcher.py and loaded with no fit at all - no rotate,
// no scale, no re-origin - so the two planes buildLauncher used to align it to are now the model's
// own responsibility. Nothing else in the game will notice if they drift; coins will just start
// leaving from inside the barrel.
//
// Coordinates are local to the launcher group, which sits at (launcherX, 0, GAME.launcherZ).
// So local y is world y, and local z + launcherZ is world z.
const MODEL = 'public/models/launcher.glb';

const box = (x, y, z) => ({ x, y, z });
const mirror = (name, spec) => ({
  [`${name}_L`]: box([-spec.x[1], -spec.x[0]], spec.y, spec.z),
  [`${name}_R`]: spec,
});

const FIN_TOP = 1.05;
const PARTS = {
  launcher_chassis: box([-0.40, 0.40], [-0.25, 0.16], [-0.92, 0.62]),
  launcher_channel: box([-0.14, 0.14], [0.16, 0.20], [-0.80, 0.66]),
  launcher_breech: box([-0.30, 0.30], [0.16, 0.95], [-0.92, -0.34]),
  launcher_core: box([-0.11, 0.11], [0.34, 0.80], [-0.96, -0.92]),
  ...mirror('launcher_vent', box([0.19, 0.26], [0.28, 0.86], [-0.95, -0.92])),
  ...mirror('launcher_fin', box([0.24, 0.30], [0.16, FIN_TOP], [-0.34, 0.20])),
  ...mirror('launcher_fin_glow', box([0.24, 0.30], [FIN_TOP, FIN_TOP + 0.03], [-0.34, 0.20])),
  launcher_barrel: box([-0.13, 0.13], [-0.06, 0.18], [0.20, 0.66]),
  launcher_muzzle: box([-0.16, 0.16], [-0.10, 0.22], [0.64, 0.70]),
};

describe('launcher model', () => {
  const gltf = readGlb(MODEL);
  const boxes = nodeBoxes(gltf);
  const bounds = overallBounds(boxes);

  it('ships no textures and borrows the machine\'s own materials', () => {
    expect(gltf.images ?? []).toHaveLength(0);
    for (const material of gltf.materials) {
      // Soft or matte variants throughout: this model sits nearest the camera, where the
      // cabinet's strengths bloom over its own silhouette.
      expect(['shell_raised', 'neon_teal_soft', 'neon_gold_soft', 'trim_gold_matte']).toContain(material.name);
    }
    expect(gltf.extensionsUsed).toContain('KHR_materials_emissive_strength');
  });

  it('holds exactly the parts the design lists', () => {
    expect(boxes.map((entry) => entry.name).sort()).toEqual(Object.keys(PARTS).sort());
  });

  describe('each part stands where the design says', () => {
    for (const { name, min, max } of boxes) {
      it(name, () => {
        const spec = PARTS[name];
        for (const [axis, key] of [[0, 'x'], [1, 'y'], [2, 'z']]) {
          expect(min[axis], `${name} ${key} min`).toBeGreaterThanOrEqual(spec[key][0] - 0.01);
          expect(max[axis], `${name} ${key} max`).toBeLessThanOrEqual(spec[key][1] + 0.01);
        }
      });
    }
  });

  // The barrel has to end exactly on the plane coins are released from. Short and they appear in
  // mid-air ahead of it; long and they spawn inside the model.
  it('ends the barrel on the muzzle plane', () => {
    expect(bounds.max[2] + GAME.launcherZ).toBeCloseTo(GAME.launcherMuzzleZ, 3);
  });

  it('stands on the mount height', () => {
    expect(bounds.min[1]).toBeCloseTo(GAME.launcherMountY, 3);
  });

  // Height is not free. The camera is at y 5.4 looking down, so a sight line grazing the top of
  // the launcher carries on and lands somewhere on the bed - and everything nearer than that
  // landing point is hidden behind the launcher. At the default geometry the machine has to stay
  // completely clear; at the geometry panel's most extreme bed the launcher may eat a little, but
  // less than a coin, or the player loses track of coins sitting on the payout lip.
  it('hides no more than a coin of the bed at any setting', () => {
    const CAMERA_Y = 5.4;
    const CAMERA_Z = -9.4;
    const topZ = GAME.launcherZ; // the fins sit around the group's own plane
    for (const [label, geometry] of [
      ['default', machineGeometryFor({})],
      ['longest bed pushed back', machineGeometryFor({ lowerCenterZ: 1.2, lowerLength: 13 })],
      ['longest bed pushed forward', machineGeometryFor({ lowerCenterZ: -0.45, lowerLength: 13 })],
    ]) {
      // Where the grazing ray reaches the bed surface.
      const reach = CAMERA_Z + (CAMERA_Y * (topZ - CAMERA_Z)) / (CAMERA_Y - bounds.max[1]);
      const hidden = Math.max(0, reach - geometry.lowerFrontZ);
      expect(hidden, `${label}: launcher hides ${hidden.toFixed(2)} of bed`).toBeLessThan(0.72);
    }
    expect(
      Math.max(0, (CAMERA_Z + (CAMERA_Y * (topZ - CAMERA_Z)) / (CAMERA_Y - bounds.max[1]))
        - machineGeometryFor({}).lowerFrontZ),
      'default geometry must be completely clear',
    ).toBe(0);
  });
});
